//VERSION = 3
//generated by the AI prompt: "can you make me a Sentinel Hub custom script that can estimate urban wealth and poverty based on Sentinel-2?
// Socio-Economic Proxy Script (Urban Wealth/Poverty)
// Proxies: High Vegetation = Wealthier; High Density/Impervious = Poorer

function setup() {
  return {
    input: ["B02", "B03", "B04", "B08", "B11", "dataMask"],
    output: { bands: 3 }
  };
}

function evaluatePixel(sample) {
  // 1. Calculate Indices
  let ndvi = (sample.B08 - sample.B04) / (sample.B08 + sample.B04);
  let ndbi = (sample.B11 - sample.B08) / (sample.B11 + sample.B08);
  let bsi = ((sample.B11 + sample.B04) - (sample.B08 + sample.B02)) / ((sample.B11 + sample.B04) + (sample.B08 + sample.B02));

  // 2. Define the Composite Channels
  // RED Channel: High Density / Built-up (Proxy for low-income/high-density)
  let red = Math.max(0, ndbi * 1.5); 
  
  // GREEN Channel: Vegetation (Proxy for high-income/planned greening)
  let green = Math.max(0, ndvi * 1.2);
  
  // BLUE Channel: Overall Reflectance/Infrastructure
  let blue = (sample.B04 + sample.B03 + sample.B02) / 3 * 2.5;

  // 3. Logic-based Coloring
  // Bright Green: Wealthy residential (lots of trees/pools)
  // Deep Red/Purple: High-density urban (potential low-income/industrial)
  // White/Grey: Balanced urban/Commercial
  // Brown: Unpaved/Informal zones (High BSI)
  
  if (bsi > 0.1 && ndvi < 0.1) {
    return [0.6, 0.4, 0.2]; // Brown for bare ground/unpaved
  }

  return [red, green, blue];
}
